    required this.blockingShareWork,
    required this.hasUnconfirmedShares,
    required this.hotkeyBound,
    required this.completedVoteArtifact,
    required this.completedForDisplay,
    this.completedVoteDisplay,
    required this.needsDraftSetup,
    required this.needsBundleSetup,
    required this.needsDelegationSigning,
    required this.hasInFlightDelegation,
    required this.delegationBundlesNeedingWork,
    required this.delegationBundlesNeedingSigning,
    required this.needsVotePolling,
    required this.hasRemainingVoteOrShareWork,
    required this.hasRecoverableVoteOrShareWork,
    required this.primaryAction,
    required this.nextSteps,
    required this.delegationStatuses,
    required this.recoveredDelegationWork,
    required this.recoveredVoteWork,
    required this.openProposals,
    required this.unrosteredIntents,
    this.immediateShareKey,
    required this.immediateShareConfirmed,
    required this.allDecided,
  });

  @override
  int get hashCode =>
