      delegationBundlesNeedingSigning.hashCode ^
      needsVotePolling.hashCode ^
      hasRemainingVoteOrShareWork.hashCode ^
      hasRecoverableVoteOrShareWork.hashCode ^
      primaryAction.hashCode ^
      nextSteps.hashCode ^
